package com.shale.data.dao;

import com.shale.core.dto.*;
import com.shale.core.runtime.DbSessionProvider;
import com.shale.core.service.MaterialRequestServicePort.*;

import java.sql.*;
import java.time.*;
import java.util.*;

public final class MaterialRequestDao {
    private final DbSessionProvider db;
    private final EntityActionAuditDao entityActionAuditDao = new EntityActionAuditDao();
    private final PhiAuditService phiAuditService;
    public MaterialRequestDao(DbSessionProvider db) { this.db = Objects.requireNonNull(db); this.phiAuditService = new PhiAuditService(new AuditLogDao(db)); }

    public List<MaterialTypeDto> listEffectiveMaterialTypes(int shaleClientId) {
        String sql = """
                WITH visible AS (
                  SELECT Id, ShaleClientId, SystemKey, Name, Description, Color, SortOrder, IsActive, IsDeleted,
                         ROW_NUMBER() OVER (PARTITION BY SystemKey ORDER BY CASE WHEN ShaleClientId = ? THEN 0 ELSE 1 END, Id) AS rn
                  FROM dbo.MaterialTypes
                  WHERE (ShaleClientId = ? OR ShaleClientId IS NULL) AND SystemKey IS NOT NULL
                )
                SELECT Id, ShaleClientId, SystemKey, Name, Description, Color, SortOrder FROM visible
                WHERE rn = 1 AND IsDeleted = 0 AND IsActive = 1
                UNION ALL
                SELECT Id, ShaleClientId, SystemKey, Name, Description, Color, SortOrder
                FROM dbo.MaterialTypes
                WHERE ShaleClientId = ? AND SystemKey IS NULL AND IsDeleted = 0 AND IsActive = 1
                ORDER BY SortOrder, Name, Id
                """;
        try (Connection con = db.requireConnection(); PreparedStatement ps = con.prepareStatement(sql)) {
            verifyTenant(con, shaleClientId); ps.setInt(1, shaleClientId); ps.setInt(2, shaleClientId); ps.setInt(3, shaleClientId);
            try (ResultSet rs = ps.executeQuery()) { List<MaterialTypeDto> out = new ArrayList<>(); while (rs.next()) out.add(new MaterialTypeDto(rs.getInt(1), (Integer)rs.getObject(2), rs.getString(3), rs.getString(4), rs.getString(5), rs.getString(6), rs.getInt(7))); return out; }
        } catch (SQLException e) { throw sqlFailure(e); }
    }

    public List<MaterialRequestSummaryDto> listMaterialRequests(long caseId, int tenant) {
        String sql = baseSelect(false) + " WHERE mr.ShaleClientId=? AND mr.CaseId=? AND mr.IsDeleted=0 AND ISNULL(c.IsDeleted,0)=0 ORDER BY mr.NextFollowUpAt, mr.RequestedAt DESC, mr.Id DESC";
        try (Connection con=db.requireConnection(); PreparedStatement ps=con.prepareStatement(sql)) { verifyTenant(con, tenant); ps.setInt(1,tenant); ps.setLong(2,caseId); try(ResultSet rs=ps.executeQuery()){List<MaterialRequestSummaryDto> out=new ArrayList<>(); while(rs.next()) out.add(mapSummary(rs)); return out;}} catch(SQLException e){throw sqlFailure(e);} }

    public MaterialRequestDetailDto findMaterialRequest(long caseId,long id,int tenant){
        String sql = baseSelect(true) + " WHERE mr.ShaleClientId=? AND mr.CaseId=? AND mr.Id=? AND mr.IsDeleted=0 AND ISNULL(c.IsDeleted,0)=0";
        try(Connection con=db.requireConnection(); PreparedStatement ps=con.prepareStatement(sql)){ verifyTenant(con,tenant); ps.setInt(1,tenant); ps.setLong(2,caseId); ps.setLong(3,id); try(ResultSet rs=ps.executeQuery()){return rs.next()?mapDetail(rs):null;}} catch(SQLException e){throw sqlFailure(e);} }

    public MaterialRequestDetailDto create(CreateMaterialRequestCommand c){ validateCreate(c); try(Connection con=db.requireConnection()){ verifyTenant(con,c.shaleClientId()); con.setAutoCommit(false); try{ validateRefs(con,c.shaleClientId(),c.caseId(),c.materialTypeId(),c.requestedByUserId(),null,c.requestedFromContactId(),c.requestedFromOrganizationId()); String title=generatedTitle(con,c.shaleClientId(),c.materialTypeId(),c.requestedFromContactId(),c.requestedFromOrganizationId(),c.title()); long id=insert(con,c,title); if(blank(c.notes())!=null) insertInitialNote(con,c,id); touchCase(con,c.caseId(),c.shaleClientId()); auditPhiCreate(con,c.actorUserId(),id,c,title); auditAction(con,c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.Action.CREATED,id,c.caseId(),Map.of(EntityActionAuditEvent.MetadataKey.CASE_ID,c.caseId(),EntityActionAuditEvent.MetadataKey.MATERIAL_TYPE_ID,c.materialTypeId(),EntityActionAuditEvent.MetadataKey.REQUEST_STATUS,norm(c.status()))); con.commit(); return findMaterialRequest(c.caseId(),id,c.shaleClientId()); }catch(Exception ex){rollback(con); throw ex;}} catch(SQLException e){throw sqlFailure(e);} }

    public MaterialRequestDetailDto update(UpdateMaterialRequestCommand c){ requireRowVer(c.expectedRowVer()); try(Connection con=db.requireConnection()){ verifyTenant(con,c.shaleClientId()); con.setAutoCommit(false); try{ MaterialRequestDetailDto old=findForUpdate(con,c.shaleClientId(),c.caseId(),c.materialRequestId()); if(old==null) throw new IllegalArgumentException("Material request not found."); assertRowVer(old.rowVer(),c.expectedRowVer()); validateRefs(con,c.shaleClientId(),c.caseId(),c.materialTypeId(),old.requestedByUserId(),c.assignedToUserId(),c.requestedFromContactId(),c.requestedFromOrganizationId()); updateRow(con,c); touchCase(con,c.caseId(),c.shaleClientId()); auditPhiUpdate(con,c.actorUserId(),old,c); auditAction(con,c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.Action.UPDATED,c.materialRequestId(),c.caseId(),Map.of(EntityActionAuditEvent.MetadataKey.CASE_ID,c.caseId(),EntityActionAuditEvent.MetadataKey.MATERIAL_TYPE_ID,c.materialTypeId())); con.commit(); return findMaterialRequest(c.caseId(),c.materialRequestId(),c.shaleClientId()); }catch(Exception ex){rollback(con); throw ex;}} catch(SQLException e){throw sqlFailure(e);} }

    public MaterialRequestDetailDto changeStatus(ChangeMaterialRequestStatusCommand c){ requireRowVer(c.expectedRowVer()); validateLifecycle(c.status(), c.requestedAt(), c.firstReceivedAt(), c.fullyReceivedAt(), c.closedAt(), c.closedByUserId(), c.closureReason()); try(Connection con=db.requireConnection()){ verifyTenant(con,c.shaleClientId()); con.setAutoCommit(false); try{ MaterialRequestDetailDto old=findForUpdate(con,c.shaleClientId(),c.caseId(),c.materialRequestId()); if(old==null) throw new IllegalArgumentException("Material request not found."); assertRowVer(old.rowVer(),c.expectedRowVer()); if(isTerminal(old.status())&&!Objects.equals(old.status(),norm(c.status()))) throw new IllegalArgumentException("Closed material requests cannot be reopened in Phase 2."); try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.MaterialRequests SET Status=?, RequestedAt=?, FirstReceivedAt=?, FullyReceivedAt=?, ClosedAt=?, ClosedByUserId=?, ClosureReason=?, UpdatedAt=SYSUTCDATETIME(), UpdatedByUserId=? WHERE ShaleClientId=? AND CaseId=? AND Id=? AND IsDeleted=0")){int i=1; ps.setString(i++,norm(c.status())); setTs(ps,i++,c.requestedAt()); setTs(ps,i++,c.firstReceivedAt()); setTs(ps,i++,c.fullyReceivedAt()); setTs(ps,i++,c.closedAt()); setInt(ps,i++,c.closedByUserId()); ps.setString(i++,blank(c.closureReason())); ps.setInt(i++,c.actorUserId()); ps.setInt(i++,c.shaleClientId()); ps.setLong(i++,c.caseId()); ps.setLong(i++,c.materialRequestId()); ps.executeUpdate();} touchCase(con,c.caseId(),c.shaleClientId()); auditAction(con,c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.Action.STATUS_CHANGED,c.materialRequestId(),c.caseId(),Map.of(EntityActionAuditEvent.MetadataKey.CASE_ID,c.caseId(),EntityActionAuditEvent.MetadataKey.PREVIOUS_REQUEST_STATUS,old.status(),EntityActionAuditEvent.MetadataKey.REQUEST_STATUS,norm(c.status()))); con.commit(); return findMaterialRequest(c.caseId(),c.materialRequestId(),c.shaleClientId()); }catch(Exception ex){rollback(con); throw ex;}} catch(SQLException e){throw sqlFailure(e);} }

    public void delete(DeleteMaterialRequestCommand c){ requireRowVer(c.expectedRowVer()); try(Connection con=db.requireConnection()){ verifyTenant(con,c.shaleClientId()); con.setAutoCommit(false); try{ MaterialRequestDetailDto old=findForUpdate(con,c.shaleClientId(),c.caseId(),c.materialRequestId()); if(old==null) throw new IllegalArgumentException("Material request not found."); assertRowVer(old.rowVer(),c.expectedRowVer()); try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.MaterialRequests SET IsDeleted=1, DeletedAt=SYSUTCDATETIME(), DeletedByUserId=?, UpdatedAt=SYSUTCDATETIME(), UpdatedByUserId=? WHERE ShaleClientId=? AND CaseId=? AND Id=? AND IsDeleted=0")){ps.setInt(1,c.actorUserId());ps.setInt(2,c.actorUserId());ps.setInt(3,c.shaleClientId());ps.setLong(4,c.caseId());ps.setLong(5,c.materialRequestId());ps.executeUpdate();} touchCase(con,c.caseId(),c.shaleClientId()); auditAction(con,c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.Action.DELETED,c.materialRequestId(),c.caseId(),Map.of(EntityActionAuditEvent.MetadataKey.CASE_ID,c.caseId())); con.commit(); }catch(Exception ex){rollback(con); throw ex;}} catch(SQLException e){throw sqlFailure(e);} }

    public List<MaterialRequestFollowUpDto> listFollowUps(long caseId,long requestId,int tenant){ String sql=""" 
        SELECT f.*, %s AS AttemptedByDisplayName FROM dbo.MaterialRequestFollowUps f JOIN dbo.MaterialRequests mr ON mr.Id=f.MaterialRequestId AND mr.ShaleClientId=f.ShaleClientId AND mr.CaseId=f.CaseId JOIN dbo.Users u ON u.Id=f.AttemptedByUserId AND u.ShaleClientId=f.ShaleClientId WHERE f.ShaleClientId=? AND f.CaseId=? AND f.MaterialRequestId=? AND mr.IsDeleted=0 ORDER BY f.AttemptedAt, f.Id
        """.formatted(userDisplayName("u")); try(Connection con=db.requireConnection();PreparedStatement ps=con.prepareStatement(sql)){verifyTenant(con,tenant);ps.setInt(1,tenant);ps.setLong(2,caseId);ps.setLong(3,requestId);try(ResultSet rs=ps.executeQuery()){List<MaterialRequestFollowUpDto> out=new ArrayList<>();while(rs.next())out.add(mapFollowUp(rs));return out;}}catch(SQLException e){throw sqlFailure(e);} }

    public FollowUpResult recordFollowUp(RecordMaterialRequestFollowUpCommand c){ requireRowVer(c.expectedRequestRowVer()); int performer = c.attemptedByUserId()==null?c.actorUserId():c.attemptedByUserId(); if(performer!=c.actorUserId()) throw new IllegalArgumentException("Follow-up performer must be the authenticated actor."); validateMethod(c.method()); if(!Set.of("NO_RESPONSE","LEFT_MESSAGE","CONTACTED","PROMISED","RECEIVED_PARTIAL","RECEIVED_COMPLETE","REFUSED","OTHER").contains(norm(c.outcome()))) throw new IllegalArgumentException("Invalid follow-up outcome."); try(Connection con=db.requireConnection()){verifyTenant(con,c.shaleClientId());con.setAutoCommit(false);try{MaterialRequestDetailDto old=findForUpdate(con,c.shaleClientId(),c.caseId(),c.materialRequestId()); if(old==null) throw new IllegalArgumentException("Material request not found."); assertRowVer(old.rowVer(),c.expectedRequestRowVer()); validateUser(con,c.shaleClientId(),performer); long id; try(PreparedStatement ps=con.prepareStatement("INSERT dbo.MaterialRequestFollowUps (ShaleClientId,MaterialRequestId,CaseId,AttemptedAt,AttemptedByUserId,Method,Outcome,NextFollowUpAt,Notes,CreatedByUserId) OUTPUT INSERTED.Id VALUES (?,?,?,?,?,?,?,?,?,?)")){int i=1;ps.setInt(i++,c.shaleClientId());ps.setLong(i++,c.materialRequestId());ps.setLong(i++,c.caseId());setTs(ps,i++,c.attemptedAt());ps.setInt(i++,performer);ps.setString(i++,norm(c.method()));ps.setString(i++,norm(c.outcome()));setTs(ps,i++,c.nextFollowUpAt());ps.setString(i++,blank(c.notes()));ps.setInt(i++,c.actorUserId());try(ResultSet rs=ps.executeQuery()){rs.next();id=rs.getLong(1);}} try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.MaterialRequests SET NextFollowUpAt=?, UpdatedAt=SYSUTCDATETIME(), UpdatedByUserId=? WHERE ShaleClientId=? AND CaseId=? AND Id=? AND IsDeleted=0")){setTs(ps,1,c.nextFollowUpAt());ps.setInt(2,c.actorUserId());ps.setInt(3,c.shaleClientId());ps.setLong(4,c.caseId());ps.setLong(5,c.materialRequestId());ps.executeUpdate();} touchCase(con,c.caseId(),c.shaleClientId()); phiAuditService.auditCreate(con,c.actorUserId(),"MaterialRequestFollowUps","Notes",id,c.notes()); phiAuditService.auditCreate(con,c.actorUserId(),"MaterialRequestFollowUps","Outcome",id,c.outcome()); auditAction(con,c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.Action.FOLLOW_UP_ADDED,c.materialRequestId(),c.caseId(),Map.of(EntityActionAuditEvent.MetadataKey.CASE_ID,c.caseId(),EntityActionAuditEvent.MetadataKey.MATERIAL_REQUEST_FOLLOW_UP_ID,id)); con.commit(); return new FollowUpResult(listFollowUps(c.caseId(),c.materialRequestId(),c.shaleClientId()).getLast(), findMaterialRequest(c.caseId(),c.materialRequestId(),c.shaleClientId()));}catch(Exception ex){rollback(con);throw ex;}}catch(SQLException e){throw sqlFailure(e);} }
    private static String baseSelect(boolean detail){ return """
        SELECT mr.Id,mr.ShaleClientId,mr.CaseId,mr.MaterialTypeId,mt.Name AS MaterialTypeName,mt.SystemKey AS MaterialTypeSystemKey,mr.Title,
               %s mr.RequestedByUserId, %s AS RequestedByDisplayName, mr.AssignedToUserId, %s AS AssignedToDisplayName,
               mr.RequestedFromContactId, %s AS RequestedFromContactDisplayName, mr.RequestedFromOrganizationId, org.Name AS RequestedFromOrganizationName, mr.RequestedFromText,
               mr.RequestMethod,mr.RequestedAt,mr.RelevantStartDate,mr.RelevantEndDate,mr.Status,mr.ExpectedResponseDate,mr.NextFollowUpAt,CAST(NULL AS datetime2) AS LastFollowUpAt,mr.FirstReceivedAt,mr.FullyReceivedAt,mr.ClosedAt,mr.ClosedByUserId,mr.ClosureReason,mr.Notes,mr.CreatedAt,mr.CreatedByUserId,mr.UpdatedAt,mr.UpdatedByUserId,mr.RowVer
        FROM dbo.MaterialRequests mr JOIN dbo.Cases c ON c.Id=mr.CaseId AND c.ShaleClientId=mr.ShaleClientId
        JOIN dbo.MaterialTypes mt ON mt.Id=mr.MaterialTypeId AND (mt.ShaleClientId=mr.ShaleClientId OR mt.ShaleClientId IS NULL)
        JOIN dbo.Users rbu ON rbu.Id=mr.RequestedByUserId AND rbu.ShaleClientId=mr.ShaleClientId AND ISNULL(rbu.is_deleted,0)=0
        LEFT JOIN dbo.Users au ON au.Id=mr.AssignedToUserId AND au.ShaleClientId=mr.ShaleClientId AND ISNULL(au.is_deleted,0)=0
        LEFT JOIN dbo.Contacts ct ON ct.Id=mr.RequestedFromContactId AND ct.ShaleClientId=mr.ShaleClientId AND ISNULL(ct.IsDeleted,0)=0
        LEFT JOIN dbo.Organizations org ON org.Id=mr.RequestedFromOrganizationId AND org.ShaleClientId=mr.ShaleClientId AND ISNULL(org.IsDeleted,0)=0
        """.formatted(detail?"mr.Description,":"CAST(NULL AS nvarchar(max)) AS Description,", userDisplayName("rbu"), userDisplayName("au"), contactDisplayName("ct")); }
    private static String userDisplayName(String alias){return "LTRIM(RTRIM(COALESCE("+alias+".name_first, '') + CASE WHEN COALESCE("+alias+".name_first, '') = '' OR COALESCE("+alias+".name_last, '') = '' THEN '' ELSE ' ' END + COALESCE("+alias+".name_last, '')))";}
    private static String contactDisplayName(String alias){return "COALESCE(NULLIF(LTRIM(RTRIM("+alias+".Name)), ''), NULLIF(LTRIM(RTRIM(CONCAT("+alias+".FirstName, ' ', "+alias+".LastName))), ''), NULLIF(LTRIM(RTRIM("+alias+".WorkName)), ''))";}
    private static MaterialRequestSummaryDto mapSummary(ResultSet rs)throws SQLException{return new MaterialRequestSummaryDto(rs.getLong("Id"),rs.getInt("ShaleClientId"),rs.getLong("CaseId"),rs.getInt("MaterialTypeId"),rs.getString("MaterialTypeName"),rs.getString("MaterialTypeSystemKey"),rs.getString("Title"),rs.getInt("RequestedByUserId"),rs.getString("RequestedByDisplayName"),(Integer)rs.getObject("AssignedToUserId"),rs.getString("AssignedToDisplayName"),(Integer)rs.getObject("RequestedFromContactId"),rs.getString("RequestedFromContactDisplayName"),(Integer)rs.getObject("RequestedFromOrganizationId"),rs.getString("RequestedFromOrganizationName"),rs.getString("RequestedFromText"),rs.getString("RequestMethod"),ldt(rs,"RequestedAt"),rs.getString("Status"),ldt(rs,"ExpectedResponseDate"),ldt(rs,"NextFollowUpAt"),ldt(rs,"LastFollowUpAt"),ldt(rs,"UpdatedAt"),rs.getBytes("RowVer"));}
    private static MaterialRequestDetailDto mapDetail(ResultSet rs)throws SQLException{return new MaterialRequestDetailDto(rs.getLong("Id"),rs.getInt("ShaleClientId"),rs.getLong("CaseId"),rs.getInt("MaterialTypeId"),rs.getString("MaterialTypeName"),rs.getString("MaterialTypeSystemKey"),rs.getString("Title"),rs.getString("Description"),rs.getInt("RequestedByUserId"),rs.getString("RequestedByDisplayName"),(Integer)rs.getObject("AssignedToUserId"),rs.getString("AssignedToDisplayName"),(Integer)rs.getObject("RequestedFromContactId"),rs.getString("RequestedFromContactDisplayName"),(Integer)rs.getObject("RequestedFromOrganizationId"),rs.getString("RequestedFromOrganizationName"),rs.getString("RequestedFromText"),rs.getString("RequestMethod"),ldt(rs,"RequestedAt"),ld(rs,"RelevantStartDate"),ld(rs,"RelevantEndDate"),rs.getString("Status"),ld(rs,"ExpectedResponseDate"),ldt(rs,"NextFollowUpAt"),ldt(rs,"LastFollowUpAt"),ldt(rs,"FirstReceivedAt"),ldt(rs,"FullyReceivedAt"),ldt(rs,"ClosedAt"),(Integer)rs.getObject("ClosedByUserId"),rs.getString("ClosureReason"),rs.getString("Notes"),ldt(rs,"CreatedAt"),rs.getInt("CreatedByUserId"),ldt(rs,"UpdatedAt"),(Integer)rs.getObject("UpdatedByUserId"),rs.getBytes("RowVer"));}
    private static MaterialRequestFollowUpDto mapFollowUp(ResultSet rs)throws SQLException{return new MaterialRequestFollowUpDto(rs.getLong("Id"),rs.getInt("ShaleClientId"),rs.getLong("MaterialRequestId"),rs.getLong("CaseId"),ldt(rs,"AttemptedAt"),rs.getInt("AttemptedByUserId"),rs.getString("AttemptedByDisplayName"),rs.getString("Method"),rs.getString("Outcome"),ldt(rs,"NextFollowUpAt"),rs.getString("Notes"),ldt(rs,"CreatedAt"),rs.getInt("CreatedByUserId"),rs.getBytes("RowVer"));}
    private long insert(Connection con,CreateMaterialRequestCommand c,String generatedTitle)throws SQLException{try(PreparedStatement ps=con.prepareStatement("INSERT dbo.MaterialRequests (ShaleClientId,CaseId,MaterialTypeId,Title,Description,RequestedByUserId,AssignedToUserId,RequestedFromContactId,RequestedFromOrganizationId,RequestedFromText,RequestMethod,RequestedAt,RelevantStartDate,RelevantEndDate,Status,ExpectedResponseDate,NextFollowUpAt,FirstReceivedAt,FullyReceivedAt,ClosedAt,ClosedByUserId,ClosureReason,Notes,CreatedByUserId) OUTPUT INSERTED.Id VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")){int i=1;ps.setInt(i++,c.shaleClientId());ps.setLong(i++,c.caseId());ps.setInt(i++,c.materialTypeId());ps.setString(i++,blank(generatedTitle));ps.setString(i++,blank(c.description()));ps.setInt(i++,c.requestedByUserId());setInt(ps,i++,null);setInt(ps,i++,c.requestedFromContactId());setInt(ps,i++,c.requestedFromOrganizationId());ps.setString(i++,blank(c.requestedFromText()));ps.setString(i++,norm(c.requestMethod()));setTs(ps,i++,c.requestedAt());setDate(ps,i++,c.relevantStartDate());setDate(ps,i++,c.relevantEndDate());ps.setString(i++,norm(c.status()));setDate(ps,i++,c.expectedResponseDate());setTs(ps,i++,c.nextFollowUpAt());setTs(ps,i++,c.firstReceivedAt());setTs(ps,i++,c.fullyReceivedAt());setTs(ps,i++,c.closedAt());setInt(ps,i++,c.closedByUserId());ps.setString(i++,blank(c.closureReason()));ps.setString(i++,blank(c.notes()));ps.setInt(i++,c.actorUserId());try(ResultSet rs=ps.executeQuery()){rs.next();return rs.getLong(1);}}}
    private void updateRow(Connection con,UpdateMaterialRequestCommand c)throws SQLException{try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.MaterialRequests SET MaterialTypeId=?,Title=?,Description=?,AssignedToUserId=?,RequestedFromContactId=?,RequestedFromOrganizationId=?,RequestedFromText=?,RequestMethod=?,RequestedAt=?,RelevantStartDate=?,RelevantEndDate=?,ExpectedResponseDate=?,NextFollowUpAt=?,Notes=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE ShaleClientId=? AND CaseId=? AND Id=? AND IsDeleted=0")){int i=1;ps.setInt(i++,c.materialTypeId());ps.setString(i++,blank(c.title()));ps.setString(i++,blank(c.description()));setInt(ps,i++,c.assignedToUserId());setInt(ps,i++,c.requestedFromContactId());setInt(ps,i++,c.requestedFromOrganizationId());ps.setString(i++,blank(c.requestedFromText()));ps.setString(i++,norm(c.requestMethod()));setTs(ps,i++,c.requestedAt());setDate(ps,i++,c.relevantStartDate());setDate(ps,i++,c.relevantEndDate());setDate(ps,i++,c.expectedResponseDate());setTs(ps,i++,c.nextFollowUpAt());ps.setString(i++,blank(c.notes()));ps.setInt(i++,c.actorUserId());ps.setInt(i++,c.shaleClientId());ps.setLong(i++,c.caseId());ps.setLong(i++,c.materialRequestId());ps.executeUpdate();}}
    private MaterialRequestDetailDto findForUpdate(Connection con,int t,long caseId,long id)throws SQLException{try(PreparedStatement ps=con.prepareStatement(baseSelect(true)+" WHERE mr.ShaleClientId=? AND mr.CaseId=? AND mr.Id=? AND mr.IsDeleted=0")){ps.setInt(1,t);ps.setLong(2,caseId);ps.setLong(3,id);try(ResultSet rs=ps.executeQuery()){return rs.next()?mapDetail(rs):null;}}}
    private void validateRefs(Connection con,int t,long caseId,int mt,int user,Integer ass,Integer contact,Integer org)throws SQLException{requireExists(con,"dbo.Cases","Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0",caseId,t); validateMaterialType(con,t,mt); validateUser(con,t,user); if(ass!=null)validateUser(con,t,ass); if(contact!=null)requireExists(con,"dbo.Contacts","Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0",contact,t); if(org!=null)requireExists(con,"dbo.Organizations","Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0",org,t);}
    private void validateMaterialType(Connection con,int t,int id)throws SQLException{try(PreparedStatement ps=con.prepareStatement("SELECT ShaleClientId,SystemKey,IsActive,IsDeleted FROM dbo.MaterialTypes WHERE Id=? AND (ShaleClientId=? OR ShaleClientId IS NULL)")){ps.setInt(1,id);ps.setInt(2,t);try(ResultSet rs=ps.executeQuery()){if(!rs.next()||!rs.getBoolean("IsActive")||rs.getBoolean("IsDeleted"))throw new IllegalArgumentException("Material type is not active for this tenant.");String key=rs.getString("SystemKey");Integer owner=(Integer)rs.getObject("ShaleClientId"); if(owner==null&&key!=null)try(PreparedStatement m=con.prepareStatement("SELECT 1 FROM dbo.MaterialTypes WHERE ShaleClientId=? AND SystemKey=?")){m.setInt(1,t);m.setString(2,key);try(ResultSet mr=m.executeQuery()){if(mr.next())throw new IllegalArgumentException("Material type is masked by tenant override.");}}}}}
    private static void requireExists(Connection con,String table,String where,Object a,Object b)throws SQLException{try(PreparedStatement ps=con.prepareStatement("SELECT 1 FROM "+table+" WHERE "+where)){ps.setObject(1,a);ps.setObject(2,b);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new IllegalArgumentException("Referenced record not found.");}}}
    private void validateUser(Connection con,int t,int u)throws SQLException{requireExists(con,"dbo.Users","Id=? AND ShaleClientId=? AND ISNULL(is_deleted,0)=0",u,t);}
    private static void validateCreate(CreateMaterialRequestCommand c){validateMethod(c.requestMethod()); validateSource(c.requestedFromContactId(),c.requestedFromOrganizationId(),c.requestedFromText()); validateLifecycle(c.status(),c.requestedAt(),c.firstReceivedAt(),c.fullyReceivedAt(),c.closedAt(),c.closedByUserId(),c.closureReason());}
    private static void validateSource(Integer c,Integer o,String text){if((c==null)==(o==null))throw new IllegalArgumentException("Exactly one requested-from Contact or Organization is required."); if(blank(text)!=null)throw new IllegalArgumentException("Free-text requested-from sources are not supported for new requests.");}
    private static void validateDates(LocalDate s,LocalDate e){if(s!=null&&e!=null&&s.isAfter(e))throw new IllegalArgumentException("Relevant start date must be on or before end date.");}
    private static void validateMethod(String m){if(!Set.of("EMAIL","PHONE","FAX","MAIL","PORTAL","IN_PERSON","OTHER").contains(norm(m)))throw new IllegalArgumentException("Invalid method.");}
    private static void validateLifecycle(String status,LocalDateTime requested,LocalDateTime first,LocalDateTime full,LocalDateTime closed,Integer closedBy,String reason){String s=norm(status); if(!Set.of("DRAFT","REQUESTED","FOLLOW_UP_DUE","PARTIALLY_RECEIVED","FULLY_RECEIVED","CLOSED","CANCELLED").contains(s))throw new IllegalArgumentException("Invalid material request status."); if(s.equals("DRAFT")&&requested!=null)throw new IllegalArgumentException("Draft requests cannot have RequestedAt."); if(!s.equals("DRAFT")&&requested==null)throw new IllegalArgumentException("RequestedAt is required after draft."); if(s.equals("PARTIALLY_RECEIVED")&&first==null)throw new IllegalArgumentException("FirstReceivedAt is required."); if(s.equals("FULLY_RECEIVED")&&full==null)throw new IllegalArgumentException("FullyReceivedAt is required."); boolean term=s.equals("CLOSED")||s.equals("CANCELLED"); if(term&&(closed==null||closedBy==null||blank(reason)==null))throw new IllegalArgumentException("Closure fields are required."); if(!term&&(closed!=null||closedBy!=null||blank(reason)!=null))throw new IllegalArgumentException("Closure fields require closed or cancelled status.");}
    private static boolean isTerminal(String s){return "CLOSED".equals(s)||"CANCELLED".equals(s);}
    private void auditPhiCreate(Connection con,int actor,long id,CreateMaterialRequestCommand c,String title){phiAuditService.auditCreate(con,actor,"MaterialRequests","Title",id,title);phiAuditService.auditCreate(con,actor,"MaterialRequests","Description",id,c.description());phiAuditService.auditCreate(con,actor,"MaterialRequests","RequestedFromText",id,c.requestedFromText());phiAuditService.auditCreate(con,actor,"MaterialRequests","Notes",id,c.notes());}
    private void auditPhiUpdate(Connection con,int actor,MaterialRequestDetailDto old,UpdateMaterialRequestCommand c){phiAuditService.auditUpdate(con,actor,"MaterialRequests","Title",old.id(),old.title(),c.title());phiAuditService.auditUpdate(con,actor,"MaterialRequests","Description",old.id(),old.description(),c.description());phiAuditService.auditUpdate(con,actor,"MaterialRequests","RequestedFromText",old.id(),old.requestedFromText(),c.requestedFromText());phiAuditService.auditUpdate(con,actor,"MaterialRequests","Notes",old.id(),old.notes(),c.notes());}

    private String generatedTitle(Connection con,int tenant,int materialTypeId,Integer contactId,Integer orgId,String historicalFallback)throws SQLException{if(blank(historicalFallback)!=null)return blank(historicalFallback);String type=lookupScalar(con,"SELECT Name FROM dbo.MaterialTypes WHERE Id=? AND (ShaleClientId=? OR ShaleClientId IS NULL)",materialTypeId,tenant);String source=contactId!=null?lookupScalar(con,"SELECT "+contactDisplayName("c")+" FROM dbo.Contacts c WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0",contactId,tenant):lookupScalar(con,"SELECT Name FROM dbo.Organizations WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0",orgId,tenant); if(blank(type)==null||blank(source)==null)return blank(historicalFallback); return type.replaceAll("(?i)\\s+requested$","").trim()+" requested from "+source.trim();}
    private static String lookupScalar(Connection con,String sql,Object a,Object b)throws SQLException{try(PreparedStatement ps=con.prepareStatement(sql)){ps.setObject(1,a);ps.setObject(2,b);try(ResultSet rs=ps.executeQuery()){return rs.next()?rs.getString(1):null;}}}
    private void insertInitialNote(Connection con,CreateMaterialRequestCommand c,long id)throws SQLException{try(PreparedStatement ps=con.prepareStatement("INSERT dbo.MaterialRequestFollowUps (ShaleClientId,MaterialRequestId,CaseId,AttemptedAt,AttemptedByUserId,Method,Outcome,NextFollowUpAt,Notes,CreatedByUserId) VALUES (?,?,?,SYSUTCDATETIME(),?,?,?,?,?,?)")){int i=1;ps.setInt(i++,c.shaleClientId());ps.setLong(i++,id);ps.setLong(i++,c.caseId());ps.setInt(i++,c.actorUserId());ps.setString(i++,norm(c.requestMethod()));ps.setString(i++,"OTHER");setTs(ps,i++,c.nextFollowUpAt());ps.setString(i++,blank(c.notes()));ps.setInt(i++,c.actorUserId());ps.executeUpdate();}}
    private void auditAction(Connection con,int t,int actor,EntityActionAuditEvent.Action action,long id,long caseId,Map<EntityActionAuditEvent.MetadataKey,?> md)throws SQLException{entityActionAuditDao.append(con,EntityActionAuditEvent.now(t,actor,EntityActionAuditEvent.EntityType.MATERIAL_REQUEST,id,action,EntityActionAuditEvent.EntityType.MATERIAL_REQUEST,id,md));}
    private static void touchCase(Connection con,long caseId,int t)throws SQLException{try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.Cases SET UpdatedAt=SYSUTCDATETIME() WHERE Id=? AND ShaleClientId=?")){ps.setLong(1,caseId);ps.setInt(2,t);ps.executeUpdate();}}
    private static void verifyTenant(Connection con,int t)throws SQLException{try(PreparedStatement ps=con.prepareStatement("SELECT CAST(SESSION_CONTEXT(N'ShaleClientId') AS INT)" );ResultSet rs=ps.executeQuery()){if(!rs.next()||rs.getInt(1)!=t)throw new IllegalStateException("ShaleClientId session context mismatch.");}}
    private static void assertRowVer(byte[] actual,byte[] expected){if(!Arrays.equals(actual,expected))throw new IllegalStateException("Material request changed.");}
    private static void requireRowVer(byte[] rv){if(rv==null||rv.length==0)throw new IllegalArgumentException("expectedRowVer is required.");}
    private static RuntimeException sqlFailure(SQLException e){return new IllegalStateException("Database operation failed.",e);} private static void rollback(Connection c){try{c.rollback();}catch(Exception ignored){}}
    private static String norm(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);} private static String blank(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
    private static LocalDateTime ldt(ResultSet rs,String c)throws SQLException{Timestamp t=rs.getTimestamp(c);return t==null?null:t.toLocalDateTime();} private static LocalDate ld(ResultSet rs,String c)throws SQLException{java.sql.Date d=rs.getDate(c);return d==null?null:d.toLocalDate();}
    private static void setTs(PreparedStatement ps,int i,LocalDateTime v)throws SQLException{if(v==null)ps.setNull(i,Types.TIMESTAMP);else ps.setTimestamp(i,Timestamp.valueOf(v));} private static void setDate(PreparedStatement ps,int i,LocalDate v)throws SQLException{if(v==null)ps.setNull(i,Types.DATE);else ps.setDate(i,java.sql.Date.valueOf(v));} private static void setInt(PreparedStatement ps,int i,Integer v)throws SQLException{if(v==null)ps.setNull(i,Types.INTEGER);else ps.setInt(i,v);} 
}
